// Core tests: the 17 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, and property cases from the
// SPEC. The PRNG draws and the shuffle traces were recomputed with an
// independent integer-arithmetic implementation (see AUTHOR-CHECK.md
// and the builder's independent Python check); the boundary values
// below were derived by hand from the SPEC's pinned limits.

import assert from "node:assert/strict";
import test from "node:test";
import {
  EXAMPLE_INPUT,
  createPrng,
  run,
} from "../public/js/core/group-generator.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const base = {
  names: "A\nB",
  mode: "count",
  groupCount: "2",
  groupSize: "",
  seed: "42",
};

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

test("PRNG: seed 42 first 8 draws match the AUTHOR-CHECK integer table", () => {
  const expected = [
    2581720956, 1925393290, 3661312704, 2876485805, 750819978, 2261697747, 1173505300,
    2683257857,
  ];
  const next = createPrng(42);
  for (const k of expected) {
    assert.equal(Math.floor(next() * 4294967296), k);
  }
});

test("PRNG: seed 0 and seed max are distinct deterministic streams", () => {
  const a = createPrng(0);
  const b = createPrng(4294967295);
  assert.notEqual(a(), b());
  assert.equal(createPrng(42)(), createPrng(42)());
});

test("example input equals the basic-count fixture input", () => {
  const basic = coreCases.find((entry) => entry.id === "basic-count");
  assert.deepEqual(EXAMPLE_INPUT, basic.input);
});

test("boundary: raw names of 32768 units pass, 32769 fail INPUT_LIMIT row null", () => {
  // The raw check runs first, so a 32769-unit single line must give
  // INPUT_LIMIT row null, while a 32768-unit single line gives
  // INPUT_LIMIT row 1 (per-line limit), proving the raw check order.
  const atLimit = "A".repeat(32768);
  assert.deepEqual(errorOf({ ...base, names: atLimit }), {
    code: "INPUT_LIMIT",
    field: "names",
    row: 1,
  });
  const overLimit = "A".repeat(32769);
  assert.deepEqual(errorOf({ ...base, names: overLimit }), {
    code: "INPUT_LIMIT",
    field: "names",
    row: null,
  });
});

test("boundary: name of exactly 40 units passes, 41 fails INPUT_LIMIT row 2", () => {
  const ok = run({ ...base, names: `小安\n${"A".repeat(40)}` });
  assert.equal(ok.ok, true);
  assert.equal(ok.result.totalNames, 2);
  assert.deepEqual(errorOf({ ...base, names: `小安\n${"A".repeat(41)}` }), {
    code: "INPUT_LIMIT",
    field: "names",
    row: 2,
  });
});

test("boundary: 500 names succeed with every name exactly once; 501 fail ROW_LIMIT row 501", () => {
  const names500 = Array.from({ length: 500 }, (_, i) => `N${i + 1}`).join("\n");
  const ok = run({ ...base, names: names500, groupCount: "7", seed: "42" });
  assert.equal(ok.ok, true);
  const all = ok.result.groups.flatMap((g) => g.members);
  assert.equal(all.length, 500);
  assert.equal(new Set(all).size, 500);
  const sizes = ok.result.groups.map((g) => g.size);
  assert.equal(Math.max(...sizes) - Math.min(...sizes) <= 1, true);
  // Larger groups first: 500 = 7 * 71 + 3, so the first 3 groups have 72.
  assert.deepEqual(sizes, [72, 72, 72, 71, 71, 71, 71]);
  const names501 = `${names500}\nN501`;
  assert.deepEqual(errorOf({ ...base, names: names501, groupCount: "7" }), {
    code: "ROW_LIMIT",
    field: "names",
    row: 501,
  });
});

test("boundary: K = N gives one per group; K = 1 puts everyone together", () => {
  const allSingle = run({ ...base, names: "A\nB\nC", groupCount: "3", seed: "42" });
  assert.equal(allSingle.ok, true);
  assert.deepEqual(
    allSingle.result.groups.map((g) => g.size),
    [1, 1, 1],
  );
  const oneGroup = run({ ...base, names: "A\nB\nC", groupCount: "1", seed: "42" });
  assert.equal(oneGroup.ok, true);
  assert.equal(oneGroup.result.groups.length, 1);
  assert.equal(oneGroup.result.groups[0].size, 3);
});

test("boundary: seed of 10 units passes, 11 fails INPUT_LIMIT; groupCount 501 is RANGE", () => {
  assert.equal(run({ ...base, seed: "4294967295" }).ok, true);
  assert.deepEqual(errorOf({ ...base, seed: "42949672950" }), {
    code: "INPUT_LIMIT",
    field: "seed",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, groupCount: "501" }), {
    code: "RANGE",
    field: "groupCount",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, groupCount: "500", names: "A\nB" }), {
    code: "RANGE",
    field: "groupCount",
    row: null,
  });
});

test("validation order: inactive field over capacity is INPUT_LIMIT even when active field is bad", () => {
  // groupSize is inactive in count mode but 4 units long; its capacity
  // failure comes before the active groupCount grammar failure.
  assert.deepEqual(
    errorOf({ ...base, groupCount: "abc", groupSize: "1234", seed: "42" }),
    { code: "INPUT_LIMIT", field: "groupSize", row: null },
  );
  assert.deepEqual(errorOf({ ...base, groupCount: "1234", groupSize: "", seed: "42" }), {
    code: "INPUT_LIMIT",
    field: "groupCount",
    row: null,
  });
});

test("validation: empty active count field is EMPTY; bad grammar is INTEGER_FORMAT", () => {
  assert.deepEqual(errorOf({ ...base, groupCount: "" }), {
    code: "EMPTY",
    field: "groupCount",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, groupCount: "03" }), {
    code: "INTEGER_FORMAT",
    field: "groupCount",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, mode: "size", groupCount: "", groupSize: "0" }), {
    code: "RANGE",
    field: "groupSize",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, seed: "" }), {
    code: "EMPTY",
    field: "seed",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, seed: "4294967296" }), {
    code: "RANGE",
    field: "seed",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, seed: "-1" }), {
    code: "INTEGER_FORMAT",
    field: "seed",
    row: null,
  });
});

test("validation: lone surrogate in a name is UNICODE with its row", () => {
  assert.deepEqual(errorOf({ ...base, names: "小安\n\uD800小柏" }), {
    code: "UNICODE",
    field: "names",
    row: 2,
  });
  assert.deepEqual(errorOf({ ...base, names: "小安\n小柏\uDC00" }), {
    code: "UNICODE",
    field: "names",
    row: 2,
  });
  // A paired surrogate (emoji) is a valid name.
  const emoji = run({ ...base, names: "小安\n\uD83D\uDE00", groupCount: "2", seed: "42" });
  assert.equal(emoji.ok, true);
});

test("validation: schema rejects missing, extra, wrong-type and accessor inputs", () => {
  assert.deepEqual(run({ names: "A", mode: "count", groupCount: "1", groupSize: "" }), {
    ok: false,
    error: { code: "SCHEMA", field: null, row: null },
  });
  assert.deepEqual(run({ ...base, extra: "x" }), {
    ok: false,
    error: { code: "SCHEMA", field: null, row: null },
  });
  assert.deepEqual(run({ ...base, seed: 42 }), {
    ok: false,
    error: { code: "SCHEMA", field: null, row: null },
  });
  assert.deepEqual(run(null), {
    ok: false,
    error: { code: "SCHEMA", field: null, row: null },
  });
  assert.deepEqual(run(["A"]), {
    ok: false,
    error: { code: "SCHEMA", field: null, row: null },
  });
  const accessor = { ...base };
  Object.defineProperty(accessor, "seed", { get: () => "42", enumerable: true });
  assert.deepEqual(run(accessor), {
    ok: false,
    error: { code: "SCHEMA", field: null, row: null },
  });
});

test("invariants: every success conserves the multiset, balances sizes, larger groups first", () => {
  const cases = [
    { names: "A\nB\nC\nD\nE\nF\nG\nH\nI\nJ", mode: "count", groupCount: "3", seed: "7" },
    { names: "A\nB\nC\nD\nE\nF\nG\nH\nI\nJ", mode: "size", groupSize: "4", seed: "42" },
    { names: "甲\n甲\n乙\n乙\n乙", mode: "count", groupCount: "2", seed: "99" },
  ];
  for (const input of cases) {
    const outcome = run({
      names: input.names,
      mode: input.mode,
      groupCount: input.groupCount ?? "",
      groupSize: input.groupSize ?? "",
      seed: input.seed,
    });
    assert.equal(outcome.ok, true);
    const { result } = outcome;
    const parsed = input.names.split("\n").slice().sort();
    const produced = result.groups.flatMap((g) => g.members).slice().sort();
    assert.deepEqual(produced, parsed);
    const sizes = result.groups.map((g) => g.size);
    assert.equal(Math.max(...sizes) - Math.min(...sizes) <= 1, true);
    for (let i = 1; i < sizes.length; i += 1) {
      assert.equal(sizes[i - 1] >= sizes[i], true);
    }
    for (const group of result.groups) {
      assert.equal(group.size, group.members.length);
      if (input.mode === "size") assert.equal(group.size <= Number(input.groupSize), true);
    }
    assert.equal(
      result.totalNames,
      result.groups.reduce((sum, g) => sum + g.size, 0),
    );
  }
});

test("determinism: same input twice gives the identical result object", () => {
  const input = { ...base, names: "甲\n乙\n丙\n丁\n戊\n己\n庚\n辛\n壬\n癸" };
  assert.deepEqual(run(input), run(input));
});

test("trim set: only space, tab and full-width space are trimmed", () => {
  // U+00A0 (non-breaking space) is NOT in the SPEC trim set.
  const outcome = run({ ...base, names: "\u00A0A\u00A0\nB", groupCount: "2", seed: "42" });
  assert.equal(outcome.ok, true);
  const all = outcome.result.groups.flatMap((g) => g.members);
  assert.equal(all.includes("\u00A0A\u00A0"), true);
});
